<script setup lang="ts">
// Day 9: Urban-rural — Tokyo through a weekday on the 1 km grid: columns of people drain from the
// suburbs into the centre by midday and flow back home at night, under a sun that rises and sets
import ThreeView, { Color, geodeticSurfaceNormal } from '@navaramap/three'
import { DefaultPlugin, type DefaultDescriptions } from '@navaramap/three-default-plugin'
import { TileJsonPlugin } from '@navaramap/three-plugins'
import { SphericalHarmonics3, Vector3 } from 'three'
import { StarfieldMeshDesc, type StarfieldConfig } from './lib/StarfieldMeshDesc'

// Generated by scripts/day09/extract_tokyo_mesh.py
const baseURL = useRuntimeConfig().app.baseURL
const dataBase = `${baseURL}data/day09`

const NAVY = '#060b1c'

// Column height: metres per person in the 1 km cell. Ōtemachi at midday, ~220,000, stands ~2.6 km
const METERS_PER_PERSON = 0.012
// Gap between neighbouring columns, as a share of the cell
const GAP = 0.1

// Color by how many people a cell gains or loses from night to day (day - night): blue for the
// bedroom towns that empty out, pale where little changes, orange to red for the centres that fill
// up. Gains and losses share one scale, on a square root so the smaller changes still show; the
// colors run out at 10,000 people either way
const LOSS = ['#f1ece2', '#8fb8de', '#2f6fb3']
const GAIN = ['#f1ece2', '#f7b049', '#e8562a', '#b3132b']
const CHANGE_MAX = 10_000
const STEPS = 32
// (Navara's Color has no lerp: mix the sRGB channels here)
const rgbOf = (hex: string) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16))
const rampOf = (stops: string[], steps = STEPS) =>
  Array.from({ length: steps }, (_, i) => {
    const t = (i / (steps - 1)) * (stops.length - 1)
    const k = Math.min(stops.length - 2, Math.floor(t))
    const [a, b] = [rgbOf(stops[k]!), rgbOf(stops[k + 1]!)]
    const hex = a.map((c, j) => Math.round(c + (b[j]! - c) * (t - k)).toString(16).padStart(2, '0')).join('')
    return new Color().setStyle(`#${hex}`)
  })
const LOSS_RAMP = rampOf(LOSS)
const GAIN_RAMP = rampOf(GAIN)
const colorOf = (night: number, day: number) => {
  const change = day - night
  const t = Math.sqrt(Math.min(1, Math.abs(change) / CHANGE_MAX))
  return (change < 0 ? LOSS_RAMP : GAIN_RAMP)[Math.round(t * (STEPS - 1))]!
}

// The clock: a weekday in 24 s. The data has two moments, late night (01-04) and midday (11-14);
// the columns move between them with the commute, out 06-10 and home 17-22
const DAY_MS = 24_000
const START_HOUR = 2
const smoothstep = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)))
  return t * t * (3 - 2 * t)
}
const daytimeOf = (hour: number) => smoothstep(6, 10, hour) * (1 - smoothstep(17, 22, hour))
// How dark it is: the basemap dims into the night from sunset and comes back at sunrise
const darkOf = (hour: number) => 1 - smoothstep(5, 7, hour) * (1 - smoothstep(17, 19, hour))
// The basemap's tint, from day to night
const DAY_TINT = '#ffffff'
const NIGHT_TINT = '#2b3554'
const TINT_STEPS = 24
// Midday on a weekday in December 2021, the data's month
const DATE = new Date('2021-12-15T03:00:00Z')
const TOKYO_LNG = 139.7

// The camera loops: all of Tokyo from the south -> in over the centre -> out west over the Tama
// suburbs, looking back east at the centre -> back out. Three days go by on the way round
const OVERVIEW = { lng: 139.5, lat: 35.45, distance: 85_000, heading: 0, pitch: -40, roll: 0 }
const CENTRE_VIEW = { lng: 139.76, lat: 35.66, distance: 24_000, heading: 330, pitch: -28, roll: 0 }
const SUBURB_VIEW = { lng: 139.4, lat: 35.68, distance: 40_000, heading: 80, pitch: -24, roll: 0 }
const STOPS: [typeof OVERVIEW, number][] = [
  [CENTRE_VIEW, 9000],
  [SUBURB_VIEW, 10_000],
  [OVERVIEW, 9000],
]
const HOLD_MS = 8000

// A fixed light for the columns, as a light probe: soft all round, stronger from high in the
// south-west over Tokyo, so the columns' sides shade apart. Spherical harmonics in world (ECEF)
// axes; three.js divides the irradiance by π for Lambert surfaces
const AMBIENT = 0.75 * Math.PI
const KEY = 0.45 * Math.PI
function fixedLight(): SphericalHarmonics3 {
  const up = geodeticSurfaceNormal({ lng: TOKYO_LNG, lat: 35.68, height: 0 })
  const east = new Vector3(0, 0, 1).cross(up).normalize()
  const north = up.clone().cross(east)
  const toLight = up.clone().multiplyScalar(1).addScaledVector(east, -0.6).addScaledVector(north, -0.8).normalize()
  const sh = new SphericalHarmonics3()
  // Irradiance from the first two bands: E(n) = 0.886 c0 + 1.023 (c1 y + c2 z + c3 x)
  const c0 = AMBIENT / 0.886227
  const c1 = KEY / 1.023328
  sh.coefficients[0]!.setScalar(c0)
  sh.coefficients[1]!.setScalar(c1 * toLight.y)
  sh.coefficients[2]!.setScalar(c1 * toLight.z)
  sh.coefficients[3]!.setScalar(c1 * toLight.x)
  return sh
}

type Mesh = { cell: [number, number]; cells: [number, number, number, number][] }

const container = ref<HTMLDivElement>()
let view: ThreeView<DefaultDescriptions> | undefined
let timer: ReturnType<typeof setTimeout> | undefined

const wait = (ms: number) => new Promise<void>((resolve) => (timer = setTimeout(resolve, ms)))

// The camera tour, with a button to stop and restart it
const touring = ref(true)
let setTouring: ((on: boolean) => void) | undefined

onMounted(async () => {
  const v = new ThreeView<DefaultDescriptions>({
    container: container.value!,
    backgroundColor: new Color().setStyle(NAVY),
    animation: true,
  })
  view = v
  v.addPlugin(new DefaultPlugin())
  const tilejson = new TileJsonPlugin()
  v.addPlugin(tilejson)
  const [mesh] = await Promise.all([fetch(`${dataBase}/tokyo_mesh.json`).then((r) => r.json() as Promise<Mesh>), v.init()])
  if (view !== v) return // unmounted while initializing
  v.registerMesh('starfield', StarfieldMeshDesc)

  v.setCamera({ ...OVERVIEW, height: 0 })

  // Day and night are told by the sky and the air (they follow the sun across the clock) and by the
  // basemap dimming; the columns keep their colors, under a fixed light
  v.atmosphere.date = DATE
  v.atmosphere.setSolarTime({ lng: TOKYO_LNG }, START_HOUR)
  const starfield: StarfieldConfig = { starfield: {} }
  v.addMesh<StarfieldMeshDesc>(starfield)
  v.addMesh({ sky: {} })
  v.addLight({ lightProbe: { sh: fixedLight() } })
  v.addEffect({ aerialPerspective: {} })
  v.addEffect({ toneMapping: {} })

  const basemap = await tilejson.addSource({
    type: 'raster-tile',
    url: 'https://papers.reearth.land/styles/papers-light/tilejson.json',
  })
  if (view !== v) return
  // Its tint takes it from day to night
  const tints = rampOf([DAY_TINT, NIGHT_TINT], TINT_STEPS)
  let tint = -1
  const basemapLayer = v.addLayer({ type: 'raster', source: basemap, raster: {} })
  const setTint = (dark: number) => {
    const t = Math.round(dark * (TINT_STEPS - 1))
    if (t === tint) return
    tint = t
    basemapLayer.update({ type: 'raster', source: basemap, raster: { color: tints[t]! } })
  }

  // One square column per cell, a little inset so the columns read apart
  const [dLng, dLat] = mesh.cell
  const inLng = (dLng * GAP) / 2
  const inLat = (dLat * GAP) / 2
  const cells = v.addSource({
    type: 'geojson',
    data: {
      type: 'FeatureCollection',
      features: mesh.cells.map(([w, s, night, day]) => {
        const [x0, y0, x1, y1] = [w + inLng, s + inLat, w + dLng - inLng, s + dLat - inLat]
        return {
          type: 'Feature' as const,
          properties: { night, day },
          geometry: { type: 'Polygon' as const, coordinates: [[[x0, y0], [x1, y0], [x1, y1], [x0, y1], [x0, y0]]] },
        }
      }),
    },
  })
  // Where the clock stands: 0 = night, 1 = midday
  let daytime = daytimeOf(START_HOUR)
  setTint(darkOf(START_HOUR))
  const columns = v.addLayer({
    type: 'vector',
    source: cells,
    polygon: { color: LOSS_RAMP[0]!, clampToGround: false },
  })
  columns.on('featureUpdated', ({ evaluator }) => {
    evaluator.evaluate(
      ({ properties }) => {
        const night = Number(properties?.['night'])
        const day = Number(properties?.['day'])
        const people = night + (day - night) * daytime
        return { color: colorOf(night, day), extrudedHeight: Math.max(10, people * METERS_PER_PERSON) }
      },
      { filters: ['night', 'day'] },
    )
  })

  // Run the clock; the columns are re-evaluated only when they would visibly change
  const startedAt = performance.now()
  v.on('preUpdate', () => {
    const hour = (START_HOUR + (24 * (performance.now() - startedAt)) / DAY_MS) % 24
    v.atmosphere.setSolarTime({ lng: TOKYO_LNG }, hour)
    setTint(darkOf(hour))
    const d = daytimeOf(hour)
    if (Math.abs(d - daytime) > 0.004) {
      daytime = d
      columns.forceUpdate()
    }
  })

  v.attribution?.add([
    {
      attributionHtml:
        'People: <a href="https://www.geospatial.jp/ckan/dataset/mlit-1km-fromto">MLIT people-flow open data</a> (Agoop), weekdays in December 2021',
    },
  ])

  const fly = (to: typeof OVERVIEW, ms: number) => v.flyTo(to, { duration: ms, easing: 'cubicInOut' })
  // Each run of the tour gets a number; stopping bumps it, so a stale run quits at its next step
  let run = 0
  const tour = async () => {
    const id = ++run
    const live = () => view === v && id === run
    while (live()) {
      for (const [to, ms] of STOPS) {
        await wait(HOLD_MS)
        if (!live()) return
        // A flight resolves false when it is cut short: by the user grabbing the camera (hand it
        // over and stop) or by the stop button (already stopped)
        if (!(await fly(to, ms))) {
          if (live()) setTouring?.(false)
          return
        }
      }
    }
  }
  setTouring = (on) => {
    touring.value = on
    if (on) {
      tour()
      return
    }
    run++
    clearTimeout(timer)
    // Cut any flight short where the camera is
    const { lng, lat, height } = v.camera.positionGeographic
    v.setCamera({ lng, lat, height, ...v.camera.orientation })
  }
  tour()
})

onBeforeUnmount(() => {
  setTouring = undefined
  clearTimeout(timer)
  view?.dispose()
  view = undefined
})
</script>

<template>
  <div class="map-canvas day09">
    <div ref="container" class="map-canvas" />
    <button type="button" class="tour" :aria-pressed="touring" @click="setTouring?.(!touring)">
      {{ touring ? '❚❚ Stop tour' : '▶ Play tour' }}
    </button>
  </div>
</template>

<style scoped>
.day09 {
  position: relative;
}

/* Matches the page's header panel */
.tour {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 10;
  padding: 8px 14px;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--fg);
  background: rgba(15, 20, 25, 0.82);
  backdrop-filter: blur(6px);
  border: 1px solid var(--border);
  border-radius: 10px;
  cursor: pointer;
}

.tour:hover {
  color: var(--accent);
}
</style>
